class DiagnosticSink(io.TextIOBase):
    """Keep library chatter out of JSONL, with explicit secret redaction."""

    def __init__(self, path: Path):
        self.handle = path.open("x", encoding="utf-8")
        self.lock = threading.Lock()
        self.pending = ""

    def write(self, value):
        with self.lock:
            self.pending += str(value)
            while "\n" in self.pending:
                line, self.pending = self.pending.split("\n", 1)
                self.handle.write(scrub(line) + "\n")
            if len(self.pending) > 1024 * 1024:
                self.pending = "[oversized diagnostic line omitted]"
            self.handle.flush()
        return len(value)

    def flush(self):
        with self.lock:
            self.handle.flush()

    def close(self):
        if not self.closed:
            super().close()
            with self.lock:
                if self.pending:
                    self.handle.write(scrub(self.pending))
                    self.pending = ""
            self.handle.close()


