"""POC evidence hook. Install only in the two controlled public profiles.

Stock gateway hooks cannot abort a turn. Public tools must independently require
the binding and recording-ready file; a failed hook leaves no usable binding.
No website content is injected: setup opens about:blank and labels only its title.
"""

from datetime import datetime, timezone
import asyncio
import json
import os
from pathlib import Path
import re
import tempfile
import threading
import time
from urllib.parse import urlsplit, urlunsplit
from urllib.request import ProxyHandler, build_opener
import uuid

from gateway.session_context import get_session_env
from hermes_cli.config import read_raw_config
from hermes_cli.profiles import get_active_profile_name, get_profile_dir
from hermes_constants import get_hermes_home


_SESSION_ID = re.compile(r"[A-Za-z0-9_-]{1,128}\Z")
_EVENTS = {"agent:start", "agent:step", "agent:end"}


def emit(home, profile, event, session_id=None, **fields):
    record = {
        "event": event,
        "utc": datetime.now(timezone.utc).isoformat(),
        "monotonic_ns": time.monotonic_ns(),
        "pid": os.getpid(),
        "thread_id": threading.get_ident(),
        "profile": profile,
        "profile_home": str(home),
        "session_id": session_id,
        "task_id": session_id,
        **fields,
    }
    data = (json.dumps(record, ensure_ascii=False, default=str) + "\n").encode("utf-8")
    fd = os.open(home / "poc-events.jsonl", os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
    try:
        if os.write(fd, data) != len(data):
            raise OSError("Short POC evidence append")
    finally:
        os.close(fd)


def atomic_json(path, value):
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    if path.parent.is_symlink() or path.is_symlink():
        raise ValueError("POC binding paths must not be symlinks")
    fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as output:
            json.dump(value, output, indent=2)
            output.write("\n")
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary, path)
    finally:
        Path(temporary).unlink(missing_ok=True)


def read_binding(path):
    if path.is_symlink():
        raise ValueError("POC binding must not be a symlink")
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError("POC binding must be an object")
    return value


def remove_owned(path, setup_id):
    if not path.exists():
        return
    if read_binding(path).get("setup_id") == setup_id:
        path.unlink()


def configuration(context, event_type):
    home = get_hermes_home().resolve()
    profile = get_active_profile_name()
    if not profile or profile == "default" or get_profile_dir(profile).resolve() != home:
        raise ValueError("POC hook requires a named public profile")
    raw = read_raw_config()
    poc = raw.get("poc") or {}
    browser = raw.get("browser") or {}
    if not isinstance(poc, dict) or not isinstance(browser, dict):
        raise ValueError("POC/browser configuration must be mappings")
    session_id = context.get("session_id")
    if not isinstance(session_id, str) or not _SESSION_ID.fullmatch(session_id):
        raise ValueError("Hook context has no valid gateway session_id")
    expected = {
        "user_id": poc.get("expected_user_id"),
        "chat_id": poc.get("channel_id"),
        "scope_id": poc.get("workspace_id"),
        "profile": profile,
    }
    for key, value in expected.items():
        if not isinstance(value, str) or not value:
            raise ValueError(f"Missing POC identity setting: {key}")
        if get_session_env(f"HERMES_SESSION_{key.upper()}", "") != value:
            raise ValueError(f"Authoritative gateway context mismatch: {key}")
    if context.get("platform") != "slack" or get_session_env("HERMES_SESSION_PLATFORM", "") != "slack":
        raise ValueError("POC hook accepts Slack turns only")
    if context.get("user_id") != expected["user_id"]:
        raise ValueError("Hook user_id does not match configured owner")
    thread_id = get_session_env("HERMES_SESSION_THREAD_ID", "")
    if not isinstance(thread_id, str) or not thread_id:
        raise ValueError("POC requires the original Slack thread root")
    if event_type != "agent:step":
        if context.get("chat_id") != expected["chat_id"] or context.get("thread_id") != thread_id:
            raise ValueError("Hook chat/thread does not match authoritative gateway context")
        if context.get("chat_type") != "group":
            raise ValueError("POC requires a test-channel mention")
    # agent:start is emitted before HERMES_SESSION_ID is bound for the model's
    # execution. Its durable ID is supplied by the gateway's trusted hook context.
    ready_value = poc.get("recording_ready_file")
    if not isinstance(ready_value, str) or not Path(ready_value).is_absolute():
        raise ValueError("poc.recording_ready_file must be an absolute path")
    ready = Path(ready_value)
    if ready.is_symlink():
        raise ValueError("Recording readiness must not be a symlink")
    wait_seconds = float(poc.get("recording_wait_seconds", 180))
    if not 0 < wait_seconds <= 180:
        raise ValueError("poc.recording_wait_seconds must be greater than zero and at most 180")
    cdp_url = browser.get("cdp_url")
    if not isinstance(cdp_url, str) or not cdp_url.strip():
        raise ValueError("Each POC profile requires browser.cdp_url")
    if os.environ.get("BROWSER_CDP_URL", "").strip():
        raise ValueError("Global BROWSER_CDP_URL would override profile selection")
    binding = {
        "session_id": session_id,
        "profile": profile,
        "profile_home": str(home),
        "platform": "slack",
        "user_id": expected["user_id"],
        "chat_id": expected["chat_id"],
        "workspace_id": expected["scope_id"],
        "thread_id": thread_id,
        "recording_ready_file": str(ready),
    }
    return home, profile, binding, cdp_url.strip(), ready, wait_seconds


def discovery_url(cdp_url):
    parsed = urlsplit(cdp_url)
    if (parsed.scheme not in {"http", "https", "ws", "wss"}
            or parsed.hostname not in {"localhost", "127.0.0.1", "::1"}
            or parsed.port is None or parsed.username or parsed.password or parsed.query or parsed.fragment):
        raise ValueError("POC CDP endpoint must be an explicit loopback URL with a port")
    scheme = "https" if parsed.scheme in {"https", "wss"} else "http"
    return urlunsplit((scheme, parsed.netloc, "/json/list", "", ""))


def discover_target(cdp_url, title):
    endpoint = discovery_url(cdp_url)
    # Loopback discovery must not be sent through an ambient HTTP proxy.
    with build_opener(ProxyHandler({})).open(endpoint, timeout=5) as response:
        targets = json.loads(response.read(1024 * 1024))
    if not isinstance(targets, list):
        raise ValueError("CDP discovery did not return a target list")
    matches = [item for item in targets if isinstance(item, dict)
               and item.get("type") == "page" and item.get("title") == title
               and item.get("url") == "about:blank"]
    if len(matches) != 1:
        raise ValueError(f"Expected exactly one labelled blank target, found {len(matches)}")
    target = matches[0]
    if not isinstance(target.get("id"), str) or not target["id"]:
        raise ValueError("CDP target has no id")
    websocket = target.get("webSocketDebuggerUrl")
    if not isinstance(websocket, str) or not websocket:
        raise ValueError("CDP target has no debugger WebSocket URL")
    target_url = urlsplit(websocket)
    source_url = urlsplit(cdp_url)
    if (target_url.scheme not in {"ws", "wss"}
            or target_url.hostname != source_url.hostname or target_url.port != source_url.port):
        raise ValueError("Discovered target does not belong to configured CDP endpoint")
    return {
        "target_id": target["id"],
        "targetId": target["id"],
        "port": source_url.port,
        "target_websocket_url": websocket,
        "webSocketDebuggerUrl": websocket,
        "cdp_url": cdp_url,
        "title": title,
        "url": "about:blank",
    }


async def prepare(context):
    home, profile, binding, cdp_url, ready, wait_seconds = configuration(context, "agent:start")
    session_id = binding["session_id"]
    binding_path = home / "poc-bindings" / f"{session_id}.json"
    target_path = home / "browser-target.json"
    setup_id = uuid.uuid4().hex
    # Revoke this session's old receipt before setup. A hook error is nonfatal to
    # Hermes, so an old receipt must not survive a failed preparation.
    if binding_path.is_symlink() or binding_path.parent.is_symlink():
        raise ValueError("POC binding path must not be a symlink")
    binding_path.unlink(missing_ok=True)
    if target_path.exists() and read_binding(target_path).get("session_id") == session_id:
        target_path.unlink()
    emit(home, profile, "agent_start", session_id, hook_event="agent:start",
         user_id=binding["user_id"], chat_id=binding["chat_id"], slack_thread_id=binding["thread_id"])
    try:
        if ready.exists():
            raise ValueError("Recording-ready file already exists; use a fresh recording gate for this run")
        discovery_url(cdp_url)  # Validate before any stock browser command runs.
        from tools.browser_tool_session import _run_browser_command

        opened = await asyncio.to_thread(_run_browser_command, session_id, "open", ["about:blank"], timeout=30)
        if not isinstance(opened, dict) or opened.get("success") is not True:
            raise RuntimeError("Stock browser prewarm failed")
        title = f"clanker-poc:{profile}:{session_id}:{setup_id}"
        expression = ("(() => { if (location.href !== 'about:blank') throw new Error('Not a blank POC tab'); "
                      f"document.title = {json.dumps(title)}; return document.title; " + "})()")
        labelled = await asyncio.to_thread(_run_browser_command, session_id, "eval", [expression], timeout=10)
        if not isinstance(labelled, dict) or labelled.get("success") is not True:
            raise RuntimeError("Stock browser could not label its blank session target")
        target = await asyncio.to_thread(discover_target, cdp_url, title)
        binding.update(setup_id=setup_id, **target)
        # The binding is published last, after prewarm AND target discovery.
        atomic_json(target_path, binding)
        atomic_json(binding_path, binding)
        emit(home, profile, "browser_target_ready", session_id, setup_id=setup_id,
             target_id=target["target_id"], recording_ready_file=str(ready), slack_thread_id=binding["thread_id"])
        deadline = time.monotonic() + wait_seconds
        while not ready.is_file():
