async def handle(event_type, context):
    if event_type not in _EVENTS:
        return
    home = get_hermes_home().resolve()
    profile = get_active_profile_name()
    session_id = context.get("session_id") if isinstance(context, dict) else None
    try:
        if not isinstance(context, dict):
            raise ValueError("Hook context must be a mapping")
        if event_type == "agent:start":
            await prepare(context)
            return
        home, profile, expected, _cdp, _ready, _wait = configuration(context, event_type)
        binding = read_binding(home / "poc-bindings" / f"{session_id}.json")
        for key, value in expected.items():
            if binding.get(key) != value:
                raise ValueError(f"Existing POC binding mismatch: {key}")
        if not binding.get("recording_gate_passed_utc"):
            raise ValueError("No completed recording gate for this session")
        fields = {
            "hook_event": event_type,
            "user_id": binding["user_id"],
            "chat_id": binding["chat_id"],
            "slack_thread_id": binding["thread_id"],
            "setup_id": binding["setup_id"],
        }
        if event_type == "agent:step":
            fields.update(iteration=context.get("iteration"), tool_names=context.get("tool_names", []))
            emit(home, profile, "agent_step", session_id, **fields)
        else:
            emit(home, profile, "agent_end", session_id, **fields)
            emit(home, profile, "task_execution_end", session_id, **fields)
    except asyncio.CancelledError:
        emit(home, profile, "setup_failed" if event_type == "agent:start" else "hook_failed", session_id,
             hook_event=event_type, reason="CancelledError")
        raise
    except Exception as error:
        emit(home, profile, "setup_failed" if event_type == "agent:start" else "hook_failed", session_id,
             hook_event=event_type, reason=f"{type(error).__name__}: {error}")
        raise
